// Committed Wikimedia photo map for the curated tourist spots (31 rows).
// Generated by scripts/fetch-spot-photos.mjs and reviewed by hand; a runtime
// edit belongs in the admin app, not here. Missing/corrupt file ⇒ no photos,
// and every caller keeps the Mapbox fallback.
const fs = require('fs');
const path = require('path');

function photoFile(){
  return process.env.LAKBAI_SPOT_PHOTOS_FILE || path.join(__dirname, 'data', 'spot-photos.json');
}
const isHttp = v => /^https?:\/\/\S+$/i.test(String(v || ''));

function photoFor(id){
  try {
    const doc = JSON.parse(fs.readFileSync(photoFile(), 'utf8'));
    const hit = doc && doc.photos && doc.photos[String(id)];
    if (!hit || !isHttp(hit.src)) return null;
    return { src: String(hit.src), page: isHttp(hit.page) ? String(hit.page) : '' };
  } catch { return null; }
}

module.exports = { photoFor, _file: photoFile };
